"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Plus, Edit2, Trash2, Eye, Copy, CheckCircle, Printer, RefreshCw, Files, LayoutGrid, List, AlertTriangle, X } from "lucide-react";
import CircularLoader from "@/components/CircularLoader";
import ConfirmModal from "@/components/ui/ConfirmModal";

interface Survey {
  id: string;
  slug: string | null;
  title: string;
  isActive: boolean;
  createdAt: string;
  _count: {
    responses: number;
  };
}

type ViewMode = "cards" | "list";

type Notice = { tone: "error" | "ok"; text: string } | null;

/**
 * لماذا فشل الطلب — بعبارةٍ تقول للمستخدم ما يفعله.
 *
 * كانت كل هذه العمليات تبتلع الفشل: `if (res.ok)` بلا else، فإن انتهت الجلسة
 * أو سُحبت الصلاحية دار الزرّ ثم سكت، فيظنّ صاحبه أن الصفحة معطّلة.
 */
async function explainFailure(res: Response, fallback: string) {
  if (res.status === 401) return "انتهت الجلسة — سجّل الدخول من جديد ثم أعد المحاولة";
  if (res.status === 403) return "ليس لديك صلاحية «الاستبيانات المخصصة»";
  try {
    const data = await res.json();
    if (data?.error) return `${fallback}: ${data.error}`;
  } catch {
    /* ردٌّ بلا JSON — يكفي الرمز */
  }
  return `${fallback} (رمز ${res.status})`;
}

// تفضيل عرض شخصي بحت (بطاقات/قائمة) لا يستحق حقلاً في قاعدة البيانات ولا مزامنة
// بين الأجهزة — يُحفظ محلياً في متصفح كل مستخدم ويُقرأ عند فتح الصفحة.
const VIEW_MODE_STORAGE_KEY = "zad_custom_surveys_view_mode";

export default function SurveysPage() {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>("cards");
  const [notice, setNotice] = useState<Notice>(null);
  // الحذف يمرّ بنافذةٍ مصمَّمة لا بـconfirm المتصفح: النافذة تسمّي الاستبيان
  // وتقول كم رداً سيذهب معه، وconfirm لا يفعل شيئاً من ذلك.
  const [pendingDelete, setPendingDelete] = useState<Survey | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  // وتوليد الرابط كذلك: يُبطل الرابط القديم عند كل من وُزِّع عليهم، فلا يُترك
  // لسؤالٍ عابرٍ من المتصفح.
  const [pendingRegenerate, setPendingRegenerate] = useState<Survey | null>(null);
  const [isRegenerating, setIsRegenerating] = useState(false);

  useEffect(() => {
    fetchSurveys();
    try {
      const saved = localStorage.getItem(VIEW_MODE_STORAGE_KEY);
      if (saved === "cards" || saved === "list") setViewMode(saved);
    } catch {
      /* localStorage غير متاح — يبقى العرض الافتراضي (بطاقات) */
    }
  }, []);

  const changeViewMode = (mode: ViewMode) => {
    setViewMode(mode);
    try {
      localStorage.setItem(VIEW_MODE_STORAGE_KEY, mode);
    } catch {
      /* تجاهل — التفضيل لن يُحفظ لكن التبديل الحالي يعمل */
    }
  };

  const fetchSurveys = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/custom-surveys");
      if (!res.ok) {
        setNotice({ tone: "error", text: await explainFailure(res, "تعذّر تحميل الاستبيانات") });
        return;
      }
      const data = await res.json();
      // ردٌّ غير مصفوفة كان يُمرَّر كما هو فتنفجر القائمة عند الرسم.
      setSurveys(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error(err);
      setNotice({ tone: "error", text: "تعذّر الاتصال بالخادم أثناء تحميل الاستبيانات" });
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = async () => {
    setIsCreating(true);
    try {
      const res = await fetch("/api/custom-surveys", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: "استبيان جديد",
          introText: "شركاؤنا في العطاء، نرحب برغبتكم في الانضمام لأسرة زاد التنموية. يهدف هذا الاستبيان لمساعدتنا في فهم واقع جمعيتكم بدقة، لنتمكن من تصميم رحلة تمكين مخصصة نحو تحقيق أثر مستدام."
        })
      });
      if (!res.ok) {
        setNotice({ tone: "error", text: await explainFailure(res, "تعذّر إنشاء الاستبيان") });
        return;
      }
      setNotice({ tone: "ok", text: "تم إنشاء استبيان جديد" });
      fetchSurveys();
    } catch (err) {
      console.error(err);
      setNotice({ tone: "error", text: "تعذّر الاتصال بالخادم أثناء إنشاء الاستبيان" });
    } finally {
      setIsCreating(false);
    }
  };

  const confirmDelete = async () => {
    if (!pendingDelete) return;
    const id = pendingDelete.id;
    setIsDeleting(true);
    try {
      const res = await fetch(`/api/custom-surveys/${id}`, { method: "DELETE" });
      if (!res.ok) {
        setNotice({ tone: "error", text: await explainFailure(res, "تعذّر حذف الاستبيان") });
        return;
      }
      setSurveys(surveys.filter(s => s.id !== id));
      setNotice({ tone: "ok", text: `حُذف «${pendingDelete.title}»` });
      setPendingDelete(null);
    } catch (err) {
      console.error(err);
      setNotice({ tone: "error", text: "تعذّر الاتصال بالخادم أثناء الحذف" });
    } finally {
      setIsDeleting(false);
    }
  };

  const handleDuplicate = async (id: string) => {
    try {
      const res = await fetch(`/api/custom-surveys/${id}/copy`, { method: "POST" });
      if (!res.ok) {
        setNotice({ tone: "error", text: await explainFailure(res, "تعذّر نسخ الاستبيان") });
        return;
      }
      setNotice({ tone: "ok", text: "نُسخ الاستبيان" });
      fetchSurveys();
    } catch (err) {
      console.error(err);
      setNotice({ tone: "error", text: "تعذّر الاتصال بالخادم أثناء النسخ" });
    }
  };

  const handleToggleActive = async (id: string, currentStatus: boolean) => {
    try {
      const res = await fetch(`/api/custom-surveys/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: !currentStatus })
      });
      if (!res.ok) {
        setNotice({
          tone: "error",
          text: await explainFailure(res, currentStatus ? "تعذّر إيقاف الاستبيان" : "تعذّر تفعيل الاستبيان"),
        });
        return;
      }
      setSurveys(surveys.map(s => s.id === id ? { ...s, isActive: !currentStatus } : s));
    } catch (err) {
      console.error(err);
      setNotice({ tone: "error", text: "تعذّر الاتصال بالخادم أثناء تغيير الحالة" });
    }
  };

  const copyLink = (id: string, slug?: string | null) => {
    const link = `${window.location.origin}/custom-survey/${slug || id}`;
    navigator.clipboard.writeText(link);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const confirmRegenerate = async () => {
    if (!pendingRegenerate) return;
    const id = pendingRegenerate.id;
    setIsRegenerating(true);
    try {
      const res = await fetch(`/api/custom-surveys/${id}/regenerate-link`, {
        method: "PUT",
      });
      if (!res.ok) {
        setNotice({ tone: "error", text: await explainFailure(res, "تعذّر توليد الرابط الجديد") });
        return;
      }
      const updatedSurvey = await res.json();
      setSurveys(surveys.map(s => s.id === id ? { ...s, slug: updatedSurvey.slug } : s));
      setNotice({ tone: "ok", text: "تم توليد الرابط الجديد — الرابط القديم لم يعد صالحاً" });
      setPendingRegenerate(null);
    } catch (err) {
      console.error(err);
      setNotice({ tone: "error", text: "تعذّر الاتصال بالخادم أثناء توليد الرابط" });
    } finally {
      setIsRegenerating(false);
    }
  };

  if (isLoading) {
    return (
      <div className="p-8 dark:bg-slate-900 min-h-screen flex items-center justify-center">
        <CircularLoader />
      </div>
    );
  }

  return (
    <div className="p-8 max-w-7xl mx-auto dark:bg-slate-900">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 dark:text-slate-100">إدارة الاستبيانات المخصصة</h1>
          <p className="text-slate-500 mt-1 dark:text-slate-400">قم بإنشاء وتعديل الاستبيانات ومتابعة الردود</p>
        </div>
        <div className="flex items-center gap-3">
          {/* تفضيل طريقة العرض — بطاقات أو قائمة، يُحفظ لهذا المستخدم في متصفحه */}
          <div className="flex items-center gap-1 p-1 bg-slate-100 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700">
            <button
              onClick={() => changeViewMode("cards")}
              title="عرض بطاقات"
              aria-pressed={viewMode === "cards"}
              className={`p-2 rounded-lg transition-all ${
                viewMode === "cards"
                  ? "bg-white text-primary shadow-sm dark:bg-slate-700"
                  : "text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"
              }`}
            >
              <LayoutGrid className="w-4 h-4" />
            </button>
            <button
              onClick={() => changeViewMode("list")}
              title="عرض قائمة"
              aria-pressed={viewMode === "list"}
              className={`p-2 rounded-lg transition-all ${
                viewMode === "list"
                  ? "bg-white text-primary shadow-sm dark:bg-slate-700"
                  : "text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"
              }`}
            >
              <List className="w-4 h-4" />
            </button>
          </div>

          <button
            onClick={handleCreate}
            disabled={isCreating}
            className="bg-primary text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-primary/90 transition-all shadow-lg shadow-primary/20 disabled:opacity-50"
          >
            {isCreating ? (
              <div className="w-5 h-5 border-2 border-white/50 border-t-white rounded-full animate-spin"></div>
            ) : (
              <Plus className="w-5 h-5" />
            )}
            إنشاء استبيان جديد
          </button>
        </div>
      </div>

      {notice && (
        <div
          role={notice.tone === "error" ? "alert" : "status"}
          className={`mb-6 flex items-start gap-2.5 rounded-xl border px-4 py-3 text-sm font-bold ${
            notice.tone === "error"
              ? "border-red-200 bg-red-50 text-red-700 dark:border-red-900/40 dark:bg-red-900/20 dark:text-red-300"
              : "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900/40 dark:bg-emerald-900/20 dark:text-emerald-300"
          }`}
        >
          {notice.tone === "error" ? (
            <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
          ) : (
            <CheckCircle className="w-4 h-4 shrink-0 mt-0.5" />
          )}
          <span className="flex-1">{notice.text}</span>
          <button
            onClick={() => setNotice(null)}
            aria-label="إغلاق"
            className="p-0.5 opacity-70 hover:opacity-100"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {surveys.length === 0 ? (
        <div className="bg-white border border-slate-200 rounded-2xl p-12 text-center shadow-sm dark:bg-slate-800 dark:border-slate-700">
          <div className="w-16 h-16 bg-primary/10 text-primary rounded-full flex items-center justify-center mx-auto mb-4">
            <Plus className="w-8 h-8" />
          </div>
          <h3 className="text-xl font-bold text-slate-800 mb-2 dark:text-slate-100">لا توجد استبيانات حالياً</h3>
          <p className="text-slate-500 mb-6 dark:text-slate-400">قم بإنشاء استبيانك المخصص الأول لتبدأ في جمع الردود.</p>
          <button
            onClick={handleCreate}
            className="bg-primary/10 text-primary font-bold px-6 py-2.5 rounded-xl hover:bg-primary hover:text-white transition-all"
          >
            إنشاء استبيان
          </button>
        </div>
      ) : viewMode === "cards" ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {surveys.map((survey) => (
            <div key={survey.id} className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm hover:shadow-md transition-all relative group flex flex-col h-full dark:bg-slate-800 dark:border-slate-700">
              <div className="flex justify-between items-start mb-4">
                <h3 className="font-bold text-lg text-slate-800 leading-tight dark:text-slate-100">{survey.title}</h3>
                <span className={`px-3 py-1 rounded-full text-xs font-bold border ${survey.isActive ? 'bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20' : 'bg-slate-50 text-slate-500 border-slate-200 dark:bg-slate-900/50 dark:text-slate-400 dark:border-slate-700'}`}>
                  {survey.isActive ? 'فعّال' : 'غير فعّال'}
                </span>
              </div>

              <div className="text-sm text-slate-500 mb-6 flex-1 dark:text-slate-400">
                تاريخ الإنشاء: {new Date(survey.createdAt).toLocaleDateString('ar-SA')}
              </div>

              <div className="flex items-center gap-3 mb-6 bg-slate-50 p-3 rounded-xl border border-slate-100 dark:bg-slate-900/50 dark:border-slate-700">
                <div className="text-center flex-1 border-l border-slate-200 dark:border-slate-700">
                  <span className="block text-2xl font-black text-primary">{survey._count.responses}</span>
                  <span className="text-xs text-slate-500 font-medium dark:text-slate-400">ردود</span>
                </div>
                <div className="flex-1 flex justify-center">
                  <button
                    onClick={() => handleToggleActive(survey.id, survey.isActive)}
                    className={`text-xs font-bold px-4 py-2 rounded-lg transition-all ${
                      survey.isActive
                        ? "bg-amber-100 text-amber-700 hover:bg-amber-200 dark:bg-amber-500/10 dark:text-amber-400 dark:hover:bg-amber-500/20"
                        : "bg-emerald-100 text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:hover:bg-emerald-500/20"
                    }`}
                  >
                    {survey.isActive ? "تعطيل الرابط" : "تفعيل الرابط"}
                  </button>
                </div>
              </div>

              <div className="flex gap-2 mt-auto">
                <Link
                  href={`/main/custom-surveys/${survey.id}/edit`}
                  className="flex-1 bg-slate-100 text-slate-700 hover:bg-slate-200 hover:text-slate-900 py-2 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all dark:bg-slate-700 dark:text-slate-300 dark:hover:bg-slate-600 dark:hover:text-slate-100"
                >
                  <Edit2 className="w-4 h-4" /> تعديل
                </Link>
                <Link
                  href={`/main/custom-surveys/${survey.id}/results`}
                  className="flex-1 bg-primary/10 text-primary hover:bg-primary hover:text-white py-2 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all"
                >
                  <Eye className="w-4 h-4" /> النتائج
                </Link>
                <Link
                  href={`/main/custom-surveys/${survey.id}/print`}
                  target="_blank"
                  className="flex-none bg-slate-100 text-slate-700 hover:bg-slate-200 hover:text-slate-900 px-3 py-2 rounded-xl flex items-center justify-center transition-all dark:bg-slate-700 dark:text-slate-300 dark:hover:bg-slate-600 dark:hover:text-slate-100"
                  title="طباعة الاستبيان"
                >
                  <Printer className="w-4 h-4" />
                </Link>
              </div>

              {/* Top Right Actions */}
              <div className="absolute top-4 left-4 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <button
                  onClick={() => setPendingRegenerate(survey)}
                  className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-amber-500 hover:border-amber-500/30 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400"
                  title="توليد رابط جديد (إلغاء القديم)"
                >
                  <RefreshCw className="w-4 h-4" />
                </button>
                <button
                  onClick={() => copyLink(survey.id, survey.slug)}
                  className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-primary hover:border-primary/30 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400"
                  title="نسخ الرابط"
                >
                  {copiedId === survey.id ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4" />}
                </button>
                <button
                  onClick={() => handleDuplicate(survey.id)}
                  className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-emerald-500 hover:border-emerald-200 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 dark:hover:border-emerald-500/30"
                  title="نسخ الاستبيان"
                >
                  <Files className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setPendingDelete(survey)}
                  className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-red-500 hover:border-red-200 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 dark:hover:border-red-500/30"
                  title="حذف"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="bg-white border border-slate-200 rounded-2xl shadow-sm divide-y divide-slate-100 dark:bg-slate-800 dark:border-slate-700 dark:divide-slate-700">
          {surveys.map((survey) => (
            <div key={survey.id} className="flex flex-col sm:flex-row sm:items-center gap-3 p-4">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <h3 className="font-bold text-sm text-slate-800 dark:text-slate-100 truncate">{survey.title}</h3>
                  <span className={`shrink-0 px-2 py-0.5 rounded-full text-[10px] font-bold border ${survey.isActive ? 'bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20' : 'bg-slate-50 text-slate-500 border-slate-200 dark:bg-slate-900/50 dark:text-slate-400 dark:border-slate-700'}`}>
                    {survey.isActive ? 'فعّال' : 'غير فعّال'}
                  </span>
                </div>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                  تاريخ الإنشاء: {new Date(survey.createdAt).toLocaleDateString('ar-SA')}
                </p>
              </div>

              <div className="flex items-center gap-4 shrink-0">
                <div className="text-center px-2">
                  <span className="block text-base font-black text-primary leading-none">{survey._count.responses}</span>
                  <span className="text-[10px] text-slate-500 dark:text-slate-400">ردود</span>
                </div>

                <button
                  onClick={() => handleToggleActive(survey.id, survey.isActive)}
                  className={`text-xs font-bold px-3 py-1.5 rounded-lg transition-all whitespace-nowrap ${
                    survey.isActive
                      ? "bg-amber-100 text-amber-700 hover:bg-amber-200 dark:bg-amber-500/10 dark:text-amber-400 dark:hover:bg-amber-500/20"
                      : "bg-emerald-100 text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:hover:bg-emerald-500/20"
                  }`}
                >
                  {survey.isActive ? "تعطيل الرابط" : "تفعيل الرابط"}
                </button>

                <div className="flex items-center gap-1 flex-wrap">
                  <Link
                    href={`/main/custom-surveys/${survey.id}/edit`}
                    className="p-2 bg-slate-100 text-slate-700 hover:bg-slate-200 hover:text-slate-900 rounded-lg transition-all dark:bg-slate-700 dark:text-slate-300 dark:hover:bg-slate-600 dark:hover:text-slate-100"
                    title="تعديل"
                  >
                    <Edit2 className="w-4 h-4" />
                  </Link>
                  <Link
                    href={`/main/custom-surveys/${survey.id}/results`}
                    className="p-2 bg-primary/10 text-primary hover:bg-primary hover:text-white rounded-lg transition-all"
                    title="النتائج"
                  >
                    <Eye className="w-4 h-4" />
                  </Link>
                  <Link
                    href={`/main/custom-surveys/${survey.id}/print`}
                    target="_blank"
                    className="p-2 bg-slate-100 text-slate-700 hover:bg-slate-200 hover:text-slate-900 rounded-lg transition-all dark:bg-slate-700 dark:text-slate-300 dark:hover:bg-slate-600 dark:hover:text-slate-100"
                    title="طباعة الاستبيان"
                  >
                    <Printer className="w-4 h-4" />
                  </Link>
                  <button
                    onClick={() => setPendingRegenerate(survey)}
                    className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-amber-500 hover:border-amber-500/30 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400"
                    title="توليد رابط جديد (إلغاء القديم)"
                  >
                    <RefreshCw className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => copyLink(survey.id, survey.slug)}
                    className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-primary hover:border-primary/30 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400"
                    title="نسخ الرابط"
                  >
                    {copiedId === survey.id ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4" />}
                  </button>
                  <button
                    onClick={() => handleDuplicate(survey.id)}
                    className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-emerald-500 hover:border-emerald-200 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 dark:hover:border-emerald-500/30"
                    title="نسخ الاستبيان"
                  >
                    <Files className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => setPendingDelete(survey)}
                    className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-red-500 hover:border-red-200 shadow-sm dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 dark:hover:border-red-500/30"
                    title="حذف"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <ConfirmModal
        isOpen={!!pendingDelete}
        title="حذف الاستبيان"
        message={
          pendingDelete
            ? `سيُحذف «${pendingDelete.title}»${
                pendingDelete._count.responses > 0
                  ? ` ومعه ${pendingDelete._count.responses} رداً مسجّلاً`
                  : ""
              }، ويبطل رابطه. لا يمكن التراجع عن هذا الإجراء.`
            : ""
        }
        confirmLabel="حذف الاستبيان"
        isPending={isDeleting}
        onCancel={() => !isDeleting && setPendingDelete(null)}
        onConfirm={confirmDelete}
      />

      <ConfirmModal
        isOpen={!!pendingRegenerate}
        title="توليد رابط جديد"
        message={
          pendingRegenerate
            ? `سيُبطل رابط «${pendingRegenerate.title}» الحالي فوراً، ومن يفتحه بعد ذلك لن يصل إلى الاستبيان. الردود المسجّلة لا تتأثر.`
            : ""
        }
        confirmLabel="توليد الرابط"
        isPending={isRegenerating}
        onCancel={() => !isRegenerating && setPendingRegenerate(null)}
        onConfirm={confirmRegenerate}
      />
    </div>
  );
}
